def move(name, entry_name, config=None):
    """
    Move an entry to the sshconfig.
    """
    if config is None:
        config = Config()

    if not config.has_section(entry_name):
        raise Exception("Entry not found.")

    if not config.has_section(name):
        config.add_section(name)

    config.set(name, entry_name, config.get(entry_name, entry_name))
    config.remove_option(entry_name, entry_name)

    config.save()

